def solve(a, b):
    # Use O(min(n, m)) space DP for Levenshtein distance
    if len(a) < len(b):
        a, b = b, a  # ensure a is the longer string
    n, m = len(a), len(b)
    # previous row
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        ai = a[i - 1]
        for j in range(1, m + 1):
            if ai == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j],      # deletion
                                 cur[j - 1],   # insertion
