def solve(s):
    """Return True if brackets in *s* are balanced, ignoring other characters.
    Accepts str, bytes, or None. Non‑string inputs are considered balanced.
    """
    # Treat None or non‑string as empty (balanced)
    if s is None:
        return True
    # If bytes, decode to string (utf‑8), ignore errors
    if isinstance(s, bytes):
        try:
            s = s.decode('utf-8')
        except Exception:
            s = ''
    # If not a string now, consider it balanced
    if not isinstance(s, str):
        return True
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openings = set(pairs.values())
    for ch in s:
        if ch in openings:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

def solve(grid):
    """Count number of islands (connected components of 1s) in a binary grid.
    Connectivity is 4-directional (up, down, left, right).
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows or j < 0 or j >= cols:
                continue
            if visited[i][j] or grid[i][j] == 0:
                continue
            visited[i][j] = True
            # explore neighbors
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and grid[i][j] == 1:
                dfs(i, j)
                count += 1
    return count

