    visited=set()
    count=0
    def dfs(i,j):
        stack=[(i,j)]
        while stack:
            x,y=stack.pop()
            if x<0 or x>=rows:
                continue
            if y<0 or y>=len(new_grid[x]):
                continue
            if (x,y) in visited or new_grid[x][y]==0:
                continue
            visited.add((x,y))
            stack.append((x-1,y))
            stack.append((x+1,y))
            stack.append((x,y-1))
            stack.append((x,y+1))
    for i in range(rows):
